from pathlib import Path
import json,hashlib,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
D=Path(__file__).resolve().parent;W=D.parents[1];C=W/'experiments/source_confidence_calibration_20261012_v1';R=C/'data_e1_run';rows=json.loads((R/'policy_records.json').read_text());states=json.loads((R/'states.json').read_text());track=np.array([x['position'][:2] for x in states]);goal=np.array(json.loads((R/'task_episode.json').read_text())['actual_episode']['goal_position_world_m'][:2]);cfg=json.loads((C/'data_e1_protocol.json').read_text());a=np.load(cfg['occupancy']);truth=a['global_origin_xy']+np.argwhere(a['grid']>0)*float(a['resolution_m']);summary=[]
def dist_segments(x,p):
 v=np.diff(p,axis=0);d=x[:,None]-p[:-1];t=np.clip((d*v).sum(2)/np.maximum((v*v).sum(1),1e-12),0,1);return np.linalg.norm(d-t[:,:,None]*v,axis=2).min(1)
for version in sorted(set(x['local_reference_version'] for x in rows)):
 ids=[i for i,x in enumerate(rows) if x['local_reference_version']==version];start,end=ids[0],ids[-1]+1
 if version==0:continue
 p=json.loads((R/'local_plans'/f'frame_{start:03d}.json').read_text());wp=p['waypoints'];xy=np.array([[v['x_m'],v['y_m']] for v in wp]);seg=np.linalg.norm(np.diff(xy,axis=0),axis=1);reverse=sum(d for d,v in zip(seg,wp[:-1]) if v['drive_direction']=='reverse');dev=dist_segments(track[start:end],xy);net=float(np.linalg.norm(track[start]-goal)-np.linalg.norm(track[end]-goal));brake=sum(rows[i].get('tracker_state_after_act',{}).get('braking_state')=='direction_change' for i in ids)*.1
 summary.append(dict(version=version,start_s=start*.1,end_s=end*.1,planned_length_m=p['path_length_m'],planned_reverse_length_m=float(reverse),planned_direction_changes=p['direction_changes'],actual_goal_progress_m=net,actual_travel_m=float(np.linalg.norm(np.diff(track[start:end+1],axis=0),axis=1).sum()),closest_reference_distance_p50_p90_m=np.quantile(dev,[.5,.9]).tolist(),direction_change_state_s=brake))
result=dict(scope='read-only explanation of existing fresh-data E1 90s; no new navigation or causal A/B',references=summary,reference_versions=len(summary),goal_remaining_m=float(np.linalg.norm(track[-1]-goal)),goal_net_progress_m=float(np.linalg.norm(track[0]-goal)-np.linalg.norm(track[-1]-goal)),actual_travel_m=float(np.linalg.norm(np.diff(track,axis=0),axis=1).sum()),direction_change_state_s=sum(x['direction_change_state_s'] for x in summary),metric_cautions='Closest segment distance is geometric only, can underestimate cursor/direction error on overlaps; reverse length is planned, not actual reverse travel; direction-change state duration is not fully stopped time.',input_sha256={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [R/'policy_records.json',R/'states.json',R/'task_episode.json',C/'data_e1_protocol.json',Path(cfg['occupancy'])]})
(D/'result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
fig,axs=plt.subplots(1,2,figsize=(13,6))
for ax,version in zip(axs,[1,2]):
 ids=[i for i,x in enumerate(rows) if x['local_reference_version']==version];i=ids[0];end=ids[-1]+1;p=json.loads((R/'local_plans'/f'frame_{i:03d}.json').read_text());xy=np.array([[v['x_m'],v['y_m']] for v in p['waypoints']]);route=np.array(p['plan_meta']['route_xy']);ax.scatter(truth[:,0],truth[:,1],s=4,c='0.85',marker='s',label='True reference (scoring only)');ax.plot(route[:,0],route[:,1],'--',c='#a05aab',lw=1.5,label='Grid guidance at installation');ax.plot(xy[:,0],xy[:,1],c='#ef8a23',lw=2,label='Installed executable reference');ax.plot(track[i:end+1,0],track[i:end+1,1],c='#2166ac',lw=2,label='Actual trajectory in this interval');ax.plot(*track[i],'o',c='#2166ac',ms=7);ax.plot(*track[end],'s',c='#2166ac',ms=7);ax.plot(*goal,'*',c='black',ms=12,label='Goal');ax.set(xlim=(-4.5,4.5),ylim=(-3.5,4.8),aspect='equal',xlabel='World X (m)',ylabel='World Y (m)',title=f'Reference {version}: {i/10:g}–{end/10:g}s');ax.legend(fontsize=8,loc='upper left')
fig.suptitle('Existing E1 data run: guidance, executable reference and actual motion\nGrey truth is not online input; dashed guidance through unknown is not certified safe');fig.tight_layout();fig.savefig(D/'E1_planned_vs_actual.png',dpi=150);plt.close(fig)
print(json.dumps(result,ensure_ascii=False,indent=2))
